{
  "name": "get_weather",
  "description": "Get current weather for a city. Use when user asks about weather conditions.",
  "parameters": {
    "type": "object",
    "properties": {
      "city": {"type": "string", "description": "City name"}
    },
    "required": ["city"]
  }
}

// 1. LLM receives user query: "What's the weather in Paris?"
// 2. LLM outputs: {"tool": "get_weather", "args": {"city": "Paris"}}
// 3. Your code executes: weather_api.get("Paris") → "22°C, cloudy"
// 4. Feed result back to LLM: "Tool result: 22°C, cloudy"
// 5. LLM generates response: "The weather in Paris is 22°C and cloudy"
